-- ============================================================
-- NES IMPORT  --  generated from the approved match table
-- Idempotent. Re-running is a no-op. Nothing is deleted.
--   17 matched units updated (gaps only)
--   134 new units inserted
--   1 NES row held out: UVC700618 (transposed pair, see match table 2a)
-- Never written: hours, vitals, engines.style, job assignment, job_meta, photos.
-- ============================================================
begin;

-- ---------- 1. MATCHED: classification (NES is authoritative) ----------
update units set klass='big', updated_at=now() where serial='TGD62507' and klass<>'big';
update units set klass='big', updated_at=now() where serial='UVC700617' and klass<>'big';
update units set klass='big', updated_at=now() where serial='X5M00207' and klass<>'big';

-- ---------- 2. MATCHED: fill blank package rating ----------
update units set kw=750, updated_at=now() where serial='C5E02984-85' and kw is null;

-- ---------- 3. MATCHED: fill blank make (never overwrite) ----------
update units set make='CAT', updated_at=now() where serial='C5E02269/70' and coalesce(make,'')='';
update units set make='Atlas Copco', updated_at=now() where serial='UVC700616' and coalesce(make,'')='';
update units set make='Atlas Copco', updated_at=now() where serial='UVC700617' and coalesce(make,'')='';
update units set make='Atlas Copco', updated_at=now() where serial='UVC700619' and coalesce(make,'')='';
update units set make='CAT', updated_at=now() where serial='X5M00207' and coalesce(make,'')='';
update units set make='CAT', updated_at=now() where serial='X5M00213' and coalesce(make,'')='';
update units set make='CAT', updated_at=now() where serial='X5M00296' and coalesce(make,'')='';
update units set make='CAT', updated_at=now() where serial='X5M00306' and coalesce(make,'')='';
update units set make='CAT', updated_at=now() where serial='X5M00357' and coalesce(make,'')='';
update units set make='CAT', updated_at=now() where serial='X5M00388' and coalesce(make,'')='';
update units set make='CAT', updated_at=now() where serial='X5M00394' and coalesce(make,'')='';
update units set make='CAT', updated_at=now() where serial='X5M00446' and coalesce(make,'')='';

-- ---------- 4. MATCHED: create engines where the NES says Twin ----------
-- Only where engines is null. style is deliberately ABSENT: the housing label is
-- physical, unset until a tech reads it, and renders as Engine 1 / Engine 2.
update units set engines='{"A": {"kvaEach": 375}, "B": {"kvaEach": 375}}'::jsonb, updated_at=now() where serial='C5E02984-85' and engines is null;
update units set engines='{"A": {"kvaEach": 625}, "B": {"kvaEach": 625}}'::jsonb, updated_at=now() where serial='TGD62501' and engines is null;
update units set engines='{"A": {"kvaEach": 625}, "B": {"kvaEach": 625}}'::jsonb, updated_at=now() where serial='TGD62504' and engines is null;
update units set engines='{"A": {"kvaEach": 625}, "B": {"kvaEach": 625}}'::jsonb, updated_at=now() where serial='TGD62507' and engines is null;
-- Config trap: these say config=TwinPak but the NES calls them SINGLES.
-- No engines statement is emitted for them, by design:
--   X5M00306  config=TwinPak  NES=500 kW
--   X5M00388  config=TwinPak  NES=500 kW
--   X5M00446  config=TwinPak  NES=500 kW

-- ---------- 5. MATCHED: append NES notes, marked, never overwriting ----------
update units set notes=case when coalesce(notes,'')='' then '[NES] No CA CARB' else notes||chr(10)||'[NES] No CA CARB' end, updated_at=now() where serial='1LS01712/14' and coalesce(notes,'') not like '%[NES]%';
update units set notes=case when coalesce(notes,'')='' then '[NES] 20''' else notes||chr(10)||'[NES] 20''' end, updated_at=now() where serial='C5E02269/70' and coalesce(notes,'') not like '%[NES]%';
update units set notes=case when coalesce(notes,'')='' then '[NES] 20''' else notes||chr(10)||'[NES] 20''' end, updated_at=now() where serial='C5E02984-85' and coalesce(notes,'') not like '%[NES]%';
update units set notes=case when coalesce(notes,'')='' then '[NES] 150 kW Loadbank' else notes||chr(10)||'[NES] 150 kW Loadbank' end, updated_at=now() where serial='TGD62501' and coalesce(notes,'') not like '%[NES]%';
update units set notes=case when coalesce(notes,'')='' then '[NES] NO Loadbank' else notes||chr(10)||'[NES] NO Loadbank' end, updated_at=now() where serial='TGD62504' and coalesce(notes,'') not like '%[NES]%';
update units set notes=case when coalesce(notes,'')='' then '[NES] 100kW Loadbank' else notes||chr(10)||'[NES] 100kW Loadbank' end, updated_at=now() where serial='TGD62507' and coalesce(notes,'') not like '%[NES]%';
update units set notes=case when coalesce(notes,'')='' then '[NES] ATLAS CopCo #2' else notes||chr(10)||'[NES] ATLAS CopCo #2' end, updated_at=now() where serial='UVC700616' and coalesce(notes,'') not like '%[NES]%';
update units set notes=case when coalesce(notes,'')='' then '[NES] ATLAS CopCo #2' else notes||chr(10)||'[NES] ATLAS CopCo #2' end, updated_at=now() where serial='UVC700617' and coalesce(notes,'') not like '%[NES]%';
update units set notes=case when coalesce(notes,'')='' then '[NES] ATLAS CopCo #4' else notes||chr(10)||'[NES] ATLAS CopCo #4' end, updated_at=now() where serial='UVC700619' and coalesce(notes,'') not like '%[NES]%';

-- ---------- 6. INSERT new units ----------
-- Unassigned, blank hours, no vitals, no label style. Hard-down from the NES is a
-- known office fact; everything else lands staged.

commit;

-- ============================================================
-- VERIFY
-- ============================================================
select count(*) as total_units from units;                              -- expect 212
select count(*) as big_iron from units where klass='big';               -- expect 153
select count(*) as twins from units where engines is not null;          -- expect 50
select count(*) as nes_hard_down from units where op_status='down';     -- expect at least 21
select count(*) as any_style_set from units where engines->>'style' is not null;  -- expect 0
-- no imported unit may carry hours or a service target:
select count(*) as imported_with_hours from units where location_type='fleet' and (current_hours is not null or service_due_hours is not null);  -- expect 0
-- the held-out transposition must NOT have been created:
select serial from units where serial in ('UVC700618','UCV700618');      -- expect UCV700618 only

-- ============================================================
-- POST-RUN VERIFICATION -- one query, one row, run once.
-- Expected values are in the comment beside each column.
-- ============================================================
select
  (select count(*) from units)                                  as total_units,          -- 212
  (select count(*) from units where klass='big')                as big_iron,             -- 153
  (select count(*) from units where klass='small')              as small_iron,           --  59
  (select count(*) from units where engines is not null)        as twins,                --  50
  (select count(*) from units where op_status='down')           as hard_down,            --  21
  (select count(*) from units where location_type='fleet')      as unassigned,           -- 134
  (select count(*) from units
     where location_type='fleet'
       and (current_hours is not null
         or service_due_hours is not null))                     as imported_with_hours,  --   0
  (select count(*) from units where engines->>'style' is not null)
                                                                as style_set,            --   0
  (select count(*) from units where serial='UVC700618')         as transposed_created,   --   0
  (select count(*) from units a join units b
      on a.id <> b.id
     and upper(regexp_replace(coalesce(a.serial,''),'[^A-Za-z0-9]','','g'))
       = upper(regexp_replace(coalesce(b.serial,''),'[^A-Za-z0-9]','','g')))
                                                                as dup_serial_rows;      --   2
-- dup_serial_rows = 2 is the KNOWN D19701 / D19701. pair, counted in both directions.
-- Any number above 2 means the import created a duplicate. It should not be able to.
